```javascript
import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Design constants
  const RIBBON_W = 7.0;
  const RIBBON_H = 0.35;
  const HAIRLINE_H = 0.006;
  const TICK_W = 0.02;
  const TICK_H = 0.14;
  const GAP_W = 0.5;
  const PADDING = 0.5;
  const FLOAT_Z = 0.02;
  const SCROLL_SPEED = 0.4;

  // Colors
  const COLORS = {
    surface: new THREE.Color(0x111117),
    hairline: new THREE.Color(0x23232b),
    tick: new THREE.Color(0xff2a38),
    paper: new THREE.Color(0xe8ecf2),
  };

  // Track resources for cleanup
  const geos = [];
  const mats = [];
  const tlLines = [];

  // 1. Base ribbon plane
  {
    const geo = new THREE.PlaneGeometry(RIBBON_W, RIBBON_H);
    const mat = new THREE.MeshStandardNodeMaterial({
      color: COLORS.surface,
      roughness: 0.6,
      metalness: 0.2,
    });
    const mesh = new THREE.Mesh(geo, mat);
    group.add(mesh);
    geos.push(geo);
    mats.push(mat);
  }

  // 2. Top and bottom hairlines
  const hairlineGeo = new THREE.PlaneGeometry(RIBBON_W, HAIRLINE_H);
  const hairlineMat = new THREE.MeshStandardNodeMaterial({
    color: COLORS.hairline,
    roughness: 0.6,
    metalness: 0.2,
  });
  geos.push(hairlineGeo);
  mats.push(hairlineMat);

  {
    const m = new THREE.Mesh(hairlineGeo, hairlineMat.clone());
    m.position.y = RIBBON_H / 2;
    m.position.z = 0.001;
    group.add(m);
    mats.push(m.material);
  }

  {
    const m = new THREE.Mesh(hairlineGeo, hairlineMat.clone());
    m.position.y = -RIBBON_H / 2;
    m.position.z = 0.001;
    group.add(m);
    mats.push(m.material);
  }

  // 3. Build ticker content
  const tickerItems = [
    'CAL NA-01 BEAT 28800 VPH',
    'POWER RESERVE 72H',
    'CASE 40.5 MM 904L',
    'REF 5811 IN STOCK',
    'WAITLIST 1204',
    'NEXT FITTING JUL 18',
  ];

  const contentGroup = new THREE.Group();
  let xPos = PADDING;

  tickerItems.forEach((text, idx) => {
    // Render text via fontAtlas
    let textMesh;
    if (ctx.fontAtlas && typeof ctx.fontAtlas.createTextMesh === 'function') {
      textMesh = ctx.fontAtlas.createTextMesh(text, {
        family: 'JetBrains Mono',
        size: 13,
        weight: 700,
        color: COLORS.paper,
        letterSpacing: 0.06,
      });
    } else if (ctx.fontAtlas && typeof ctx.fontAtlas.render === 'function') {
      textMesh = ctx.fontAtlas.render(text, {
        family: 'JetBrains Mono',
        fontSize: 13,
        weight: 700,
        color: COLORS.paper,
      });
    } else {
      textMesh = new THREE.Group();
    }

    // Estimate text width (mono: ~0.065 units per char at scale)
    const estimatedW = text.length * 0.065;
    let measuredW = estimatedW;

    if (
      textMesh.geometry &&
      typeof textMesh.geometry.computeBoundingBox === 'function'
    ) {
      textMesh.geometry.computeBoundingBox();
      if (textMesh.geometry.boundingBox) {
        measuredW =
          textMesh.geometry.boundingBox.max.x -
          textMesh.geometry.boundingBox.min.x;
      }
    }

    textMesh.position.set(xPos + measuredW / 2, 0, FLOAT_Z);
    contentGroup.add(textMesh);
    xPos += measuredW;

    // Add separator tick (except after last entry)
    if (idx < tickerItems.length - 1) {
      xPos += GAP_W;

      const tickGeo = new THREE.PlaneGeometry(TICK_W, TICK_H);
      const tickMat = new THREE.MeshStandardNodeMaterial({
        color: COLORS.tick,
        emissive: COLORS.tick,
        emissiveIntensity: 1.5,
        roughness: 0.6,
        metalness: 0.2,
      });
      const tick = new THREE.Mesh(tickGeo, tickMat);
      tick.position.set(xPos + TICK_W / 2, 0, FLOAT_Z);
      contentGroup.add(tick);

      geos.push(tickGeo);
      mats.push(tickMat);

      xPos += TICK_W + GAP_W;
    }
  });

  xPos += PADDING;
  const stripWidth = xPos;

  // 4. Create scroll container with duplicated content for seamless loop
  const scrollContainer = new THREE.Group();

  const strip1 = contentGroup.clone();
  scrollContainer.add(strip1);

  const strip2 = contentGroup.clone();
  strip2.position.x = stripWidth;
  scrollContainer.add(strip2);

  group.add(scrollContainer);

  // 5. Apply fly-through primitive or fallback to GSAP
  if (ctx.primitives && typeof ctx.primitives['fly-through'] === 'function') {
    ctx.primitives['fly-through'](scrollContainer, {
      speed: SCROLL_SPEED,
      depthUnits: 0,
    });
  } else {
    // Fallback: manual GSAP animation
    const loopDuration = stripWidth / SCROLL_SPEED;
    const tl = gsap.to(scrollContainer.position, {
      x: -stripWidth,
      duration: loopDuration,
      ease: 'none',
      repeat: -1,
      repeatDelay: 0,
    });
    tlLines.push(tl);
  }

  // 6. Cleanup
  group.userData.cleanup = () => {
    tlLines.forEach((tl) => tl.kill());
    gsap.killTweensOf(scrollContainer.position);
    geos.forEach((g) => g.dispose());
    mats.forEach((m) => m.dispose());
  };

  return group;
}
